//! Wolfram block-preconditioner replay.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `wolfram/block_golden.wls`) carries the exact inverse action of a 2-block
//! nonsymmetric matrix, per audit-sonium-solvers-preconditioners-20260921
//! (small-block actions and transposed variants). The 2x2 blocks are dense,
//! so ILUT with zero dropping factorizes them exactly and this pins the full
//! block-Jacobi action, not just its sparsity pattern.

use serde::Deserialize;
use sonium_solvers_core::traits::Preconditioner;
use sonium_solvers_preconditioners::{BlockJacobiPreconditioner, IlutConfig};
use sonium_solvers_sparse::CsrMatrix;

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    a: Vec<Vec<String>>,
    b: Vec<String>,
    inverse_b: Vec<String>,
    inverse_tb: Vec<String>,
}

fn parse(value: &str) -> f64 {
    value.parse().expect("fixture value is a decimal")
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture =
        serde_json::from_str(FIXTURE).expect("valid block-preconditioner fixture");
    assert_eq!(
        fixture.schema,
        "sonium-solvers-preconditioners.wolfram-golden.v1"
    );
    fixture
}

fn exact_preconditioner(matrix: &CsrMatrix<f64>) -> BlockJacobiPreconditioner<f64> {
    BlockJacobiPreconditioner::try_from_csr(
        matrix,
        2,
        IlutConfig {
            drop_tolerance: 0.0,
            fill_factor: 4,
            ..Default::default()
        },
    )
    .expect("exact block-Jacobi construction")
}

#[test]
fn block_jacobi_apply_matches_wolfram_inverse() {
    let fixture = parse_fixture();
    let triplets = fixture
        .a
        .iter()
        .enumerate()
        .flat_map(|(i, row)| {
            row.iter()
                .enumerate()
                .map(move |(j, value)| (i, j, parse(value)))
        })
        .collect();
    let matrix = CsrMatrix::from_triplets(4, 4, triplets);
    let precond = exact_preconditioner(&matrix);
    let b: Vec<f64> = fixture.b.iter().map(|value| parse(value)).collect();
    let expected: Vec<f64> = fixture.inverse_b.iter().map(|value| parse(value)).collect();
    let actual = precond.apply(&b);
    assert_eq!(actual.len(), expected.len());
    for (index, (got, want)) in actual.iter().zip(expected.iter()).enumerate() {
        assert!(
            (got - want).abs() <= 1e-10 * want.abs().max(1.0),
            "apply[{index}]: {got:e} != {want:e}"
        );
    }
}

#[test]
fn block_jacobi_transpose_matches_wolfram_inverse_transpose() {
    let fixture = parse_fixture();
    let triplets = fixture
        .a
        .iter()
        .enumerate()
        .flat_map(|(i, row)| {
            row.iter()
                .enumerate()
                .map(move |(j, value)| (i, j, parse(value)))
        })
        .collect();
    let matrix = CsrMatrix::from_triplets(4, 4, triplets);
    let precond = exact_preconditioner(&matrix);
    let b: Vec<f64> = fixture.b.iter().map(|value| parse(value)).collect();
    let expected: Vec<f64> = fixture
        .inverse_tb
        .iter()
        .map(|value| parse(value))
        .collect();
    let actual = precond.apply_transpose(&b);
    assert_eq!(actual.len(), expected.len());
    for (index, (got, want)) in actual.iter().zip(expected.iter()).enumerate() {
        assert!(
            (got - want).abs() <= 1e-10 * want.abs().max(1.0),
            "apply_transpose[{index}]: {got:e} != {want:e}"
        );
    }
}
